CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_caracteristica_producto`(IN `p_codigo_producto` VARCHAR(50), IN `p_nueva_caracteristica` VARCHAR(255), OUT `p_mensaje` VARCHAR(255))
BEGIN
    DECLARE v_producto_existe INT;

    
    SELECT COUNT(*) INTO v_producto_existe
    FROM productos
    WHERE codigo = p_codigo_producto AND estado = 'ACTIVO';

    IF v_producto_existe = 0 THEN
        SET p_mensaje = 'Producto no encontrado o inactivo';
    ELSE
