CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cancelar_sesion_escaneo`(IN `p_id_sesion` INT, OUT `p_mensaje` VARCHAR(255))
BEGIN
    DECLARE v_estado VARCHAR(20);
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_mensaje = 'Error al cancelar sesi??n';
    END;

    START TRANSACTION;
    
    SELECT estado INTO v_estado
    FROM sesiones_escaneo 
    WHERE id_sesion = p_id_sesion;
    
    IF v_estado != 'ACTIVA' THEN
        SET p_mensaje = 'La sesi??n no est?? activa';
        ROLLBACK;
    ELSE
        
        DELETE FROM detalles_escaneo WHERE id_sesion = p_id_sesion;
        
        
        UPDATE sesiones_escaneo 
        SET estado = 'CANCELADA', fecha_fin = CURRENT_TIMESTAMP
        WHERE id_sesion = p_id_sesion;
        
        SET p_mensaje = 'Sesi??n cancelada correctamente';
        COMMIT;
    END IF;
END ;;
DELIMITER ;
