CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_consultar_historial_movimientos`()
BEGIN
    SELECT 
        b.nombre AS Bodega,
        p.codigo AS Codigo,
        p.caracteristica,
        u.nombre AS Usuario,
        m.cantidad_anterior,
        m.cantidad_nueva,
        m.fecha
    FROM historial m
    INNER JOIN productos p 
        ON m.id_producto = p.id_producto
    INNER JOIN bodegas b 
        ON m.id_bodega = b.id_bodega
    INNER JOIN usuarios u 
        ON m.id_usuario = u.id_usuario
    ORDER BY m.fecha DESC;
END ;;
