CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_consultar_stock_producto`(IN `p_codigo_producto` VARCHAR(50))
BEGIN
    SELECT 
        b.nombre AS bodega,
        p.codigo,
        p.caracteristica,
        i.cantidad_disponible,
        i.cantidad_reservada,
