/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_finalizar_producto_terminada`(
    IN `p_id_producto` INT,
    IN `p_codigo_final` VARCHAR(50),
    IN `p_caracteristica` VARCHAR(50),
    IN `p_cantidad` INT,
    IN `p_bodega_consumo` INT,
    IN `p_bodega_destino` INT,
    IN `p_id_usuario` INT,
    IN `p_tipo_movimiento` ENUM('ENTRADA','PROCESO','COMPLETO'),
    IN `p_observaciones` TEXT,
    IN `p_crear_producto_nuevo` TINYINT,
    OUT `p_mensaje` VARCHAR(255)
)
BEGIN
    DECLARE v_id_producto_destino INT DEFAULT NULL;
    DECLARE v_cantidad_disponible INT DEFAULT 0;
    DECLARE v_error_message TEXT DEFAULT '';

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error_message = MESSAGE_TEXT;
        SET p_mensaje = CONCAT('Error SQL: ', v_error_message);
        ROLLBACK;
    END;

    START TRANSACTION;

    
    SELECT cantidad_disponible INTO v_cantidad_disponible
    FROM inventario
    WHERE id_producto = p_id_producto
      AND id_bodega = p_bodega_consumo
    FOR UPDATE;

    IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN
        SET p_mensaje = CONCAT('Stock insuficiente en bodega ', p_bodega_consumo);
        ROLLBACK;

    ELSE
        
        UPDATE inventario
        SET cantidad_disponible = cantidad_disponible - p_cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id_producto = p_id_producto
          AND id_bodega = p_bodega_consumo;

        
        IF p_crear_producto_nuevo = 1 THEN
            
            SELECT id_producto INTO v_id_producto_destino
            FROM productos
            WHERE codigo = p_codigo_final
            LIMIT 1;

            IF v_id_producto_destino IS NULL THEN
                INSERT INTO productos (codigo, caracteristica, estado)
                VALUES (p_codigo_final, TRIM(p_caracteristica), 'ACTIVO');
                SET v_id_producto_destino = LAST_INSERT_ID();
            ELSE
                UPDATE productos
                SET caracteristica = TRIM(p_caracteristica),
                    estado = 'ACTIVO'
                WHERE id_producto = v_id_producto_destino;
            END IF;
        ELSE
            
            SET v_id_producto_destino = p_id_producto;

            
            IF TRIM(p_caracteristica) <> '' THEN
                UPDATE productos
                SET caracteristica = TRIM(p_caracteristica),
                    estado = 'ACTIVO'
                WHERE id_producto = v_id_producto_destino;
            END IF;
        END IF;

        
        INSERT INTO inventario (id_producto, id_bodega, cantidad_disponible)
        VALUES (v_id_producto_destino, p_bodega_destino, p_cantidad)
        ON DUPLICATE KEY UPDATE
            cantidad_disponible = cantidad_disponible + p_cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP;

        
        INSERT INTO movimientos (
            id_producto,
            id_bodega_origen,
            id_bodega_destino,
            id_usuario_responsable,
            tipo_movimiento,
            cantidad,
            observaciones
        )
        VALUES (
            p_id_producto,
            p_bodega_consumo,
            p_bodega_destino,
            p_id_usuario,
            p_tipo_movimiento,
            p_cantidad,
            p_observaciones
        );

        SET p_mensaje = CONCAT('OK - Codigo: ', p_codigo_final);
        COMMIT;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_finalizar_sesion_escaneo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = cp850 */ ;
/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_finalizar_sesion_escaneo`(IN `p_id_sesion` INT, OUT `p_mensaje` VARCHAR(255))
BEGIN
    DECLARE v_id_bodega INT;
    DECLARE v_id_usuario INT;
    DECLARE v_total_productos INT DEFAULT 0;
    DECLARE v_done INT DEFAULT FALSE;
    DECLARE v_id_producto INT;
    DECLARE v_cantidad INT;
    DECLARE v_codigo_producto VARCHAR(50);

    
    DECLARE cur_productos CURSOR FOR
        SELECT d.id_producto, d.cantidad_escaneada
        FROM detalles_escaneo d
        WHERE d.id_sesion = p_id_sesion;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_mensaje = 'Error al finalizar sesi??n de escaneo';
    END;

    START TRANSACTION;
    
    
    SELECT id_bodega, id_usuario INTO v_id_bodega, v_id_usuario
    FROM sesiones_escaneo 
    WHERE id_sesion = p_id_sesion AND estado = 'ACTIVA';
    
    IF v_id_bodega IS NULL THEN
        SET p_mensaje = 'Sesi??n no encontrada o no activa';
        ROLLBACK;
    ELSE
        
        OPEN cur_productos;
        read_loop: LOOP
    FETCH cur_productos INTO v_id_producto, v_cantidad;
    IF v_done THEN
        LEAVE read_loop;
    END IF;

    
    SELECT codigo 
    INTO v_codigo_producto
    FROM productos
    WHERE id_producto = v_id_producto;

    INSERT INTO inventario (id_producto, id_bodega, cantidad_disponible)
    VALUES (v_id_producto, v_id_bodega, v_cantidad)
    ON DUPLICATE KEY UPDATE 
        cantidad_disponible = cantidad_disponible + v_cantidad,
        fecha_actualizacion = CURRENT_TIMESTAMP;

    INSERT INTO movimientos (
        id_producto,
        id_bodega_destino,
        id_usuario_responsable,
        tipo_movimiento,
        cantidad,
        observaciones
    )
    VALUES (
        v_id_producto,
        v_id_bodega,
        v_id_usuario,
        'ENTRADA',
        v_cantidad,
        CONCAT('PPC', v_codigo_producto)
    );

    SET v_total_productos = v_total_productos + 1;

END LOOP;
        CLOSE cur_productos;
        
        
        UPDATE sesiones_escaneo 
        SET estado = 'FINALIZADA', 
            fecha_fin = CURRENT_TIMESTAMP,
            total_productos = v_total_productos
        WHERE id_sesion = p_id_sesion;
        
        SET p_mensaje = CONCAT('Sesi??n finalizada. ', v_total_productos, ' productos procesados');
        COMMIT;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_iniciar_sesion_escaneo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = cp850 */ ;
/*!50003 SET character_set_results = cp850 */ ;
/*!50003 SET collation_connection  = cp850_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_iniciar_sesion_escaneo`(IN `p_id_bodega` INT, IN `p_id_usuario` INT, IN `p_observaciones` TEXT, OUT `p_id_sesion` INT, OUT `p_mensaje` VARCHAR(255))
proc: BEGIN
    DECLARE v_sesiones_activas INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_mensaje = 'Error al iniciar sesi??n de escaneo';
        SET p_id_sesion = 0;
    END;

    START TRANSACTION;
    
    IF p_id_bodega <> 1 THEN
        SET p_mensaje = 'Solo se permite iniciar sesi??n en la bodega principal';
        SET p_id_sesion = 0;
        ROLLBACK;
        LEAVE proc;
    END IF;
    
    
    SELECT COUNT(*) INTO v_sesiones_activas
    FROM sesiones_escaneo 
    WHERE id_bodega = p_id_bodega AND id_usuario = p_id_usuario AND estado = 'ACTIVA';
    
    IF v_sesiones_activas > 0 THEN
        SET p_mensaje = 'Ya tiene una sesi??n activa en esta bodega';
        SET p_id_sesion = 0;
        ROLLBACK;
    ELSE
        INSERT INTO sesiones_escaneo (id_bodega, id_usuario, observaciones)
        VALUES (p_id_bodega, p_id_usuario, p_observaciones);
        
        SET p_id_sesion = LAST_INSERT_ID();
        SET p_mensaje = 'Sesi??n iniciada correctamente';
        COMMIT;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_insertar_usuario` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
