CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_insertar_usuario`(IN `_id_bodega` INT, IN `_nombre` VARCHAR(100), IN `_correo` VARCHAR(150), IN `_contrasena` VARCHAR(255), IN `_rol` VARCHAR(50), IN `_estado` ENUM('ACTIVO','INACTIVO'))
BEGIN
    DECLARE user_count INT DEFAULT 0;
    
    
    SELECT COUNT(*) INTO user_count FROM usuarios WHERE correo = _correo;
    
    IF user_count > 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'El correo ya est?? registrado',
        MYSQL_ERRNO = 1062;
    ELSE
        
        INSERT INTO usuarios (id_bodega, nombre, correo, contrasena, rol, estado, fecha_creacion)
        VALUES (_id_bodega, _nombre, _correo, _contrasena, _rol, _estado, NOW());
        
        
        SELECT 
            ROW_COUNT() AS affected_rows,
            LAST_INSERT_ID() AS id_usuario;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
