CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_login`(IN `_nombre` VARCHAR(100))
BEGIN
    SELECT 
        u.id_usuario,
        u.id_bodega,
        b.nombre AS nombre_bodega,
        u.nombre,
        u.contrasena,
        u.rol
    FROM usuarios u
    LEFT JOIN bodegas b ON u.id_bodega = b.id_bodega
    WHERE u.nombre = _nombre;
END ;;
DELIMITER ;
