/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_transferir_productos`(IN `p_id_bodega_origen` INT, IN `p_id_bodega_destino` INT, IN `p_codigo_producto` VARCHAR(50), IN `p_cantidad` INT, IN `p_id_usuario` INT, IN `p_observaciones` TEXT, IN `p_tipo_movimiento` ENUM('ENTRADA','PROCESO','COMPLETO'), OUT `p_mensaje` VARCHAR(255))
main: BEGIN

    DECLARE v_id_producto INT DEFAULT NULL;

    DECLARE v_cantidad_disponible INT DEFAULT 0;

    DECLARE v_error_message TEXT DEFAULT '';



    DECLARE EXIT HANDLER FOR SQLEXCEPTION

    BEGIN

        GET DIAGNOSTICS CONDITION 1 v_error_message = MESSAGE_TEXT;

        SET p_mensaje = CONCAT('Error SQL: ', v_error_message);

        ROLLBACK;

    END;



    SET p_mensaje = NULL;



    START TRANSACTION;



    SELECT id_producto

    INTO v_id_producto

    FROM productos

    WHERE codigo = p_codigo_producto

      AND estado = 'ACTIVO'

    LIMIT 1;



    IF v_id_producto IS NULL THEN

        SET p_mensaje = 'Producto no encontrado';

        ROLLBACK;

        LEAVE main;

    END IF;



    IF p_tipo_movimiento IN ('COMPLETO', 'PROCESO')

       AND p_id_bodega_origen IN (23, 2, 21, 6, 25) THEN



        SET v_cantidad_disponible = 0;



        SELECT cantidad_disponible

        INTO v_cantidad_disponible

        FROM inventario

        WHERE id_producto = v_id_producto

          AND id_bodega = p_id_bodega_destino

        FOR UPDATE;



        IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN

            SET p_mensaje = 'Stock insuficiente en bodega destino';

            ROLLBACK;

            LEAVE main;

        END IF;



        UPDATE inventario

        SET cantidad_disponible = cantidad_disponible - p_cantidad,

            fecha_actualizacion = CURRENT_TIMESTAMP

        WHERE id_producto = v_id_producto

          AND id_bodega = p_id_bodega_destino;



        INSERT INTO inventario (

            id_producto,

            id_bodega,

            cantidad_disponible

        )

        VALUES (

            v_id_producto,

            p_id_bodega_origen,

            p_cantidad

        )

        ON DUPLICATE KEY UPDATE

            cantidad_disponible = cantidad_disponible + p_cantidad,

            fecha_actualizacion = CURRENT_TIMESTAMP;



    ELSE



        SET v_cantidad_disponible = 0;



        SELECT cantidad_disponible

        INTO v_cantidad_disponible

        FROM inventario

        WHERE id_producto = v_id_producto

          AND id_bodega = p_id_bodega_origen

        FOR UPDATE;



        IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN

            SET p_mensaje = 'Stock insuficiente en origen';

            ROLLBACK;

            LEAVE main;

        END IF;



        UPDATE inventario

        SET cantidad_disponible = cantidad_disponible - p_cantidad,

            fecha_actualizacion = CURRENT_TIMESTAMP

        WHERE id_producto = v_id_producto

          AND id_bodega = p_id_bodega_origen;



        INSERT INTO inventario (

            id_producto,

            id_bodega,

            cantidad_disponible

        )

        VALUES (

            v_id_producto,

            p_id_bodega_destino,

            p_cantidad

        )

        ON DUPLICATE KEY UPDATE

            cantidad_disponible = cantidad_disponible + p_cantidad,

            fecha_actualizacion = CURRENT_TIMESTAMP;



    END IF;



    IF NOT (p_tipo_movimiento = 'COMPLETO' AND p_id_bodega_origen = 23) THEN



        IF p_id_bodega_destino = 23

           AND p_tipo_movimiento = 'COMPLETO' THEN



            SET v_cantidad_disponible = 0;



            SELECT cantidad_disponible

            INTO v_cantidad_disponible

            FROM inventario

            WHERE id_producto = v_id_producto

              AND id_bodega = 5

            FOR UPDATE;



            IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN

                SET p_mensaje = 'Stock insuficiente en Guarnecida Proceso';

                ROLLBACK;

                LEAVE main;

            END IF;



            UPDATE inventario

            SET cantidad_disponible = cantidad_disponible - p_cantidad,

                fecha_actualizacion = CURRENT_TIMESTAMP

            WHERE id_producto = v_id_producto

              AND id_bodega = 5;



        END IF;



        IF p_id_bodega_destino = 21

           AND p_tipo_movimiento = 'COMPLETO' THEN



            SET v_cantidad_disponible = 0;



            SELECT cantidad_disponible

            INTO v_cantidad_disponible

            FROM inventario

            WHERE id_producto = v_id_producto

              AND id_bodega = 2

            FOR UPDATE;



            IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN

                SET p_mensaje = 'Stock insuficiente en Montaje Proceso';

                ROLLBACK;

                LEAVE main;

            END IF;



            UPDATE inventario

            SET cantidad_disponible = cantidad_disponible - p_cantidad,

                fecha_actualizacion = CURRENT_TIMESTAMP

            WHERE id_producto = v_id_producto

              AND id_bodega = 2;



            SET v_cantidad_disponible = 0;



            SELECT cantidad_disponible

            INTO v_cantidad_disponible

            FROM inventario

            WHERE id_producto = v_id_producto

              AND id_bodega = 23

            FOR UPDATE;



            IF IFNULL(v_cantidad_disponible, 0) < p_cantidad THEN

                SET p_mensaje = 'Stock insuficiente en Guarnecida Completo';

                ROLLBACK;

                LEAVE main;

            END IF;



            UPDATE inventario

            SET cantidad_disponible = cantidad_disponible - p_cantidad,

                fecha_actualizacion = CURRENT_TIMESTAMP

            WHERE id_producto = v_id_producto

              AND id_bodega = 23;



        END IF;



    END IF;



    INSERT INTO movimientos (

        id_producto,

        id_bodega_origen,

        id_bodega_destino,

        id_usuario_responsable,

        tipo_movimiento,

        cantidad,

        observaciones

    )

    VALUES (

        v_id_producto,

        p_id_bodega_origen,

        p_id_bodega_destino,

        p_id_usuario,

        p_tipo_movimiento,

        p_cantidad,

        p_observaciones

    );



    IF p_tipo_movimiento = 'COMPLETO' AND p_id_bodega_origen = 23 THEN

        SET p_mensaje = 'Consumo realizado correctamente';

    ELSE

        SET p_mensaje = 'Transferencia realizada correctamente';

    END IF;



    COMMIT;

END ;;
DELIMITER ;
